## Runtime support for the code generated by f2nim from Magboltz.
##
## Everything here reproduces what gfortran (-O0 -ffp-contract=off) does:
## column-major arrays, DO loop trip counts, `x**n` via libgcc's __powidf2,
## formatted output (FORMAT edit descriptors I, F, E, D, A, X, /, strings,
## groups and reversion) and list-directed input/output.

import std/[math, strutils, tables]
import unchained
import rm48, farrays
export rm48, math, farrays

# ---------------------------------------------------------------- DO loops

template fdo*(v: untyped, a, b: typed, body: untyped) =
  ## DO v = a, b: bounds evaluated once, trip count fixed in advance,
  ## v = b+1 after normal completion.
  let lo = typeof(v)(a)
  let hi = typeof(v)(b)
  v = lo
  var trip = hi - lo + 1
  while trip > 0:
    body
    v += 1
    dec trip

template fdo*(v: untyped, a, b, s: typed, body: untyped) =
  ## DO v = a, b, s
  let lo = typeof(v)(a)
  let hi = typeof(v)(b)
  let st = typeof(v)(s)
  v = lo
  var trip = (hi - lo + st) div st
  while trip > 0:
    body
    v += st
    dec trip

# ---------------------------------------------------------------- arithmetic

proc powidf2(x: cdouble, n: cint): cdouble {.importc: "__powidf2".}
proc powisf2(x: cfloat, n: cint): cfloat {.importc: "__powisf2".}

func pow2*(x: float64): float64 {.inline.} = x*x
func pow2*(x: float32): float32 {.inline.} = x*x
proc powi*(x: float64, n: SomeInteger): float64 {.inline.} =
  ## x**n for integer n > 2 (gfortran calls libgcc's __powidf2)
  float64(powidf2(cdouble(x), cint(n)))
proc powi*(x: float32, n: SomeInteger): float32 {.inline.} =
  float32(powisf2(cfloat(x), cint(n)))
func ipow*[T: SomeInteger](x: T, n: SomeInteger): T =
  result = 1
  for i in 1..n: result = result * x
func nint*(x: SomeFloat): int32 {.inline.} =
  ## Fortran NINT: round half away from zero
  int32(round(x))
func fsign*[T: SomeFloat](a, b: T): T {.inline.} = copySign(a, b)

# ---------------------------------------------------------------- characters

func fstr*(s: string, n: int): string =
  ## assignment to CHARACTER*n: pad with blanks or truncate
  if s.len >= n: s[0 ..< n] else: s & repeat(' ', n - s.len)

# ---------------------------------------------------------------- STOP

proc fstop*() {.noreturn.} =
  stdout.flushFile
  quit(0)

# ---------------------------------------------------------------- formatted output

type
  FValKind* = enum fvInt, fvReal, fvStr, fvBool
  FVal* = object
    case kind*: FValKind
    of fvInt: i*: int64
    of fvReal: f*: float64
    of fvStr: s*: string
    of fvBool: b*: bool

converter toFVal*(x: int): FVal = FVal(kind: fvInt, i: x)
converter toFVal*(x: int32): FVal = FVal(kind: fvInt, i: x)
converter toFVal*(x: float64): FVal = FVal(kind: fvReal, f: x)
converter toFVal*(x: float32): FVal = FVal(kind: fvReal, f: float64(x))
converter toFVal*(x: string): FVal = FVal(kind: fvStr, s: x)
converter toFVal*(x: bool): FVal = FVal(kind: fvBool, b: x)
converter toFVal*[T: SomeUnit](x: T): FVal = FVal(kind: fvReal, f: x.float)
  ## a quantity, in its unit

type
  EdKind = enum edStr, edX, edSlash, edI, edF, edE, edD, edA, edGroup
  Ed = object
    kind: EdKind
    rep: int
    w, d: int            ## d = -1: not given
    s: string
    items: seq[Ed]

proc parseFormat(f: string): seq[Ed] =
  var i = 0
  proc skip() =
    while i < f.len and f[i] in {' ', ','}: inc i
  proc num(): int =
    result = -1
    var j = i
    while j < f.len and f[j] in Digits: inc j
    if j > i: result = parseInt(f[i ..< j])
    i = j
  proc parseList(stopAt: char): seq[Ed] =
    while true:
      skip()
      if i >= f.len: raise newException(ValueError, "unterminated format: " & f)
      if f[i] == stopAt:
        inc i
        return
      if f[i] == '\'':
        var s = ""
        inc i
        while true:
          if f[i] == '\'':
            if i+1 < f.len and f[i+1] == '\'':
              s.add '\''; i += 2; continue
            inc i
            break
          s.add f[i]; inc i
        result.add Ed(kind: edStr, s: s, rep: 1)
        continue
      if f[i] == '/':
        result.add Ed(kind: edSlash, rep: 1)
        inc i
        continue
      var rep = num()
      if f[i] == '(':
        inc i
        result.add Ed(kind: edGroup, rep: max(rep, 1), items: parseList(')'))
        continue
      let c = f[i].toUpperAscii
      inc i
      case c
      of 'X': result.add Ed(kind: edX, rep: max(rep, 1))
      of 'I', 'F', 'E', 'D', 'A':
        let w = num()
        var d = -1
        if i < f.len and f[i] == '.':
          inc i
          d = num()
        let k = (case c
          of 'I': edI
          of 'F': edF
          of 'E': edE
          of 'D': edD
          else: edA)
        result.add Ed(kind: k, rep: max(rep, 1), w: w, d: d)
      else: raise newException(ValueError, "unsupported edit descriptor " & c & " in " & f)
  var f0 = f.strip
  i = 0
  if f0.len == 0 or f0[0] != '(': raise newException(ValueError, "bad format " & f)
  let f = f0
  inc i
  result = parseList(')')

var fmtCache {.threadvar.}: Table[string, seq[Ed]]

proc stars(w: int): string = repeat('*', w)

proc fmtI(x: int64, w: int): string =
  result = $x
  if w > 0:
    if result.len > w: return stars(w)
    result = align(result, w)

proc c_snprintf(buf: cstring, n: csize_t, fmt: cstring): cint {.importc: "snprintf",
  header: "<stdio.h>", varargs.}

proc printfF(x: float64, d: int): string =
  ## exactly rounded fixed-point digits of |x| (glibc printf), always with '.'
  var buf: array[400, char]
  let n = c_snprintf(cast[cstring](addr buf[0]), csize_t(buf.len), "%#.*f", cint(d), abs(x))
  result = newString(n)
  for k in 0 ..< n: result[k] = buf[k]

proc printfE(x: float64, d: int): (string, int) =
  ## d significant digits of |x| and the decimal exponent of 0.ddd form
  var buf: array[64, char]
  let n = c_snprintf(cast[cstring](addr buf[0]), csize_t(buf.len), "%.*e", cint(d-1), abs(x))
  var s = newString(n)
  for k in 0 ..< n: s[k] = buf[k]
  let e = s.find('e')
  let digits = s[0 ..< e].replace(".", "")
  (digits, parseInt(s[e+1 .. ^1]) + 1)

proc fmtNonFinite(x: float64, w: int): string =
  ## NaN / Infinity in F, E, D editing, as libgfortran's build_infnan_string
  ## (no SP: a positive infinity gets no sign, NaN never one)
  let neg = x < 0
  if w < 3 or (neg and w == 3): return stars(w)
  var s = if x != x: "NaN" elif w - ord(neg) >= 8: "Infinity" else: "Inf"
  if neg: s = "-" & s
  align(s, w)

proc fmtF*(x: float64, w, d: int): string =
  if x != x or abs(x) == Inf: return fmtNonFinite(x, w)
  var s = printfF(x, d)
  let neg = signbit(x)
  if s.startsWith("0.") and (s.len + ord(neg)) > w: s = s[1 .. ^1]
  if neg: s = "-" & s
  if s.len > w: return stars(w)
  align(s, w)

proc fmtE*(x: float64, w, d: int, letter: char): string =
  if x != x or abs(x) == Inf: return fmtNonFinite(x, w)
  var digits: string
  var ex: int
  if x == 0:
    digits = repeat('0', d)
    ex = 0
  else:
    (digits, ex) = printfE(x, d)
  var exs: string
  let ax = abs(ex)
  if ax <= 99: exs = letter & (if ex < 0: "-" else: "+") & align($ax, 2, '0')
  elif ax <= 999: exs = (if ex < 0: "-" else: "+") & $ax
  else: return stars(w)
  var s = "0." & digits & exs
  let neg = signbit(x)
  if s.len + ord(neg) > w: s = s[1 .. ^1]
  if neg: s = "-" & s
  if s.len > w: return stars(w)
  align(s, w)

proc fmtA(s: string, w: int): string =
  if w < 0: s
  elif s.len >= w: s[0 ..< w]
  else: align(s, w)

type WState = object
  o: File
  rec: string
  pending: int             ## spaces from X, emitted only if something follows
  k: int                   ## next item
  done: bool

proc put(w: var WState, s: string) =
  if w.pending > 0:
    w.rec.add repeat(' ', w.pending)
    w.pending = 0
  w.rec.add s

proc endRecord(w: var WState) =
  w.o.write w.rec, "\n"
  w.rec = ""
  w.pending = 0

proc run(w: var WState, list: seq[Ed], items: openArray[FVal], fmt: string) =
  for ed in list:
    if w.done: return
    for r in 1 .. ed.rep:
      if w.done: return
      case ed.kind
      of edStr: w.put(ed.s)
      of edX: w.pending += 1
      of edSlash: w.endRecord()
      of edGroup: w.run(ed.items, items, fmt)
      else:
        if w.k >= items.len:
          w.done = true
          return
        let v = items[w.k]
        inc w.k
        case ed.kind
        of edI:
          if v.kind != fvInt: raise newException(ValueError, "I edit for non-integer in " & fmt)
          w.put fmtI(v.i, ed.w)
        of edF, edE, edD:
          if v.kind != fvReal: raise newException(ValueError, "real edit for non-real in " & fmt)
          w.put(case ed.kind
            of edF: fmtF(v.f, ed.w, ed.d)
            of edE: fmtE(v.f, ed.w, ed.d, 'E')
            else: fmtE(v.f, ed.w, ed.d, 'D'))
        of edA:
          if v.kind != fvStr: raise newException(ValueError, "A edit for non-string in " & fmt)
          w.put fmtA(v.s, ed.w)
        else: discard

proc fwrite*(o: File, fmt: string, items: varargs[FVal, toFVal]) =
  ## WRITE(6, fmt) items, to o; nothing if o is nil
  if o == nil: return
  if fmt notin fmtCache: fmtCache[fmt] = parseFormat(fmt)
  let eds = fmtCache[fmt]
  var w = WState(o: o)
  # first pass through the whole format, then reversion while items remain
  w.run(eds, items, fmt)
  if not w.done and w.k < items.len:
    var revert = eds
    for i in countdown(eds.high, 0):
      if eds[i].kind == edGroup:
        revert = eds[i .. ^1]
        break
    var guard = 0
    while not w.done and w.k < items.len:
      w.endRecord()
      let before = w.k
      w.run(revert, items, fmt)
      if w.k == before:
        inc guard
        if guard > 1: raise newException(ValueError, "format without data edit descriptors: " & fmt)
  w.endRecord()

proc fwrite*(o: File, fmt: string, items: seq[FVal]) =
  fwrite(o, fmt, varargs[FVal](items))

proc fwrite*(fmt: string, items: varargs[FVal, toFVal]) =
  ## WRITE(6, fmt) items
  fwrite(stdout, fmt, items)

# ---------------------------------------------------------------- list-directed input

type ListReader* = object
  toks: seq[string]
  pos: int
  stopped: bool

proc listRead*(): ListReader =
  ## READ(5, *): starts reading at the next record
  var line: string
  if not stdin.readLine(line):
    stderr.writeLine "Fortran runtime error: End of file"
    quit(2)
  result.toks = line.replace(',', ' ').splitWhitespace

proc nextTok(r: var ListReader): string =
  while r.pos >= r.toks.len:
    var line: string
    if not stdin.readLine(line):
      stderr.writeLine "Fortran runtime error: End of file"
      quit(2)
    r.toks = line.replace(',', ' ').splitWhitespace
    r.pos = 0
  result = r.toks[r.pos]
  inc r.pos
  if result == "/" : r.stopped = true
  elif '*' in result:
    raise newException(ValueError, "repeat counts in list input not implemented: " & result)

proc c_strtod(s: cstring, endp: ptr cstring): cdouble {.importc: "strtod", header: "<stdlib.h>".}

proc get*(r: var ListReader, x: var float64) =
  if r.stopped: return
  let t = r.nextTok
  if r.stopped: return
  x = float64(c_strtod(t.replace('D', 'E').replace('d', 'e').cstring, nil))

proc get*(r: var ListReader, x: var SomeInteger) =
  if r.stopped: return
  let t = r.nextTok
  if r.stopped: return
  x = typeof(x)(parseBiggestInt(t))
